import assert from'node:assert/strict';import type{GeneratedBody}from'../../src/core/generators/definition';import facts from'./legacy-2017-autumn-business-facts.json';import{businessReviewedEmploymentAlt}from'./legacy-2017-autumn-business-svg';
const text=(blocks:GeneratedBody['choices'][number])=>{assert.equal(blocks.length,1);assert(blocks[0].type==='paragraph');return blocks[0].text;};
/** Literal full prose is reviewed separately; fixed semantic tuples/graphs do not
 * invoke the producer's mapping, model, cases, correct index or explanation. */
export function legacy2017AutumnBusinessOracle(source:string,body:GeneratedBody,values:readonly number[]){assert.equal(values.length,1);assert(Number.isInteger(values[0]));const f=facts.conditions.find(f=>f.source===source&&f.variant===values[0]);assert(f);const n=Number(source.split('-').at(-1));assert.equal(body.prompt.length,[71,79].includes(n)?2:1);assert(body.prompt[0].type==='paragraph');assert.equal(body.prompt[0].text,f.fullStem);assert.deepEqual(body.choices.map(text),f.fullChoices);assert.equal(body.explanation,f.explanation);let truth:boolean[];
 if(n===70)truth=['shared-standard','inimitable-advantage',values[0]?'shared-api':'shared-instructions','general-parts'].map(x=>x==='inimitable-advantage');
 else if(n===71){const target=body.prompt[0].text.match(/，([abcd])に該当するもの/)?.[1];assert(target);const t=body.prompt[1];assert(t.type==='table');assert.equal(t.caption,'基本要素とデバイス・サービスの例');assert.deepEqual(t.columns,['基本要素','デバイス・サービスの例']);assert.deepEqual(t.rows,[['データの収集','a'],['データの伝送','b'],['データの解析','c'],['データの活用','d']]);const semantic:Record<string,string>={a:'measure',b:'transmit',c:'analyze',d:'use'};truth=['analyze','measure','transmit','use'].map(x=>x===semantic[target]);}
 else if(n===72)truth=[values[0]?'customer-design-then-manufacture':'customer-manufacture','kanban-ticket','parallel-design','BOM-component-requirements'].map(x=>x==='BOM-component-requirements');
 else if(n===73)truth=['energy-conversion','material-cycle',values[0]?'resistance-heating':'heat-transfer','home-network-energy-control'].map(x=>x==='home-network-energy-control');
 else if(n===74)truth=['physical-sensing','image-data-classification-learning','engine-idle-control',values[0]?'traffic-data-route-reflection':'software-map-update'].map(x=>x==='image-data-classification-learning');
 else if(n===75)truth=['enterprise-strategy-investment',values[0]?'performance-configuration-execution':'operations-improvement-instructions','independent-system-audit','incident-response-instructions'].map(x=>x==='enterprise-strategy-investment');
 else if(n===76)truth=['uniform-general-education','on-job-guidance',values[0]?'independent-of-instruction-time':'independent-of-instructor-quality','off-job'].map(x=>x==='on-job-guidance');
 else if(n===77){const targets=[['point','balance'],['period','income-expense'],['period','cash'],['period','equity-movement']],target=targets[values[0]];assert(target);truth=[['period','equity-movement'],['period','cash'],['period','income-expense'],['point','balance']].map(x=>JSON.stringify(x)===JSON.stringify(target));}
 else if(n===79){const g={contract:{employment:['A-C'],instruction:['A-C']},secondment:{employment:['A-C','B-C'],instruction:['B-C']},dispatch:{employment:['A-C'],instruction:['B-C']}};truth=[values[0]?g.contract.instruction.includes('A-C')&&!g.contract.instruction.includes('B-C'):g.contract.instruction.includes('B-C'),values[0]?!g.secondment.instruction.includes('B-C'):g.secondment.instruction.includes('B-C'),g.dispatch.employment.includes('B-C'),false];const b=body.prompt[1];assert(b.type==='diagram'&&b.scene.kind==='source_figure');assert.equal(b.scene.profile,'legacy-2017-employment-contracts');assert.deepEqual(b.scene.values,[0]);assert.equal(b.caption,'企業と労働者の関係');assert.equal(b.alt,businessReviewedEmploymentAlt);}
 else{assert.equal(n,80);assert.equal(f.fullChoices[1],'電子消費者契約法');if(values[0])assert.match(body.prompt[0].text,/一定の期間・金額の要件.*契約書面.*中途解約/);truth=['commercial','electronic-consumer-contract','specified-transactions','unfair-competition'].map(x=>x==='specified-transactions');}
 assert.deepEqual(truth,f.truth);assert.equal(truth.filter(Boolean).length,1);assert.equal(body.correctIndex,truth.indexOf(true));return truth;
}
